import {animationFrame} from '../data/combat.js';
export class SpriteRenderer {
 constructor(){this.player=new Image();this.player.src='./assets/sion-animation.png';this.enemies=new Image();this.enemies.src='./assets/enemies.png';}
 cell(c,image,column,row,columns,rows,x,y,width,height){if(!image.complete||!image.naturalWidth)return false;const sw=image.naturalWidth/columns,sh=image.naturalHeight/rows;c.drawImage(image,column*sw+1,row*sh+1,sw-2,sh-2,x,y,width,height);return true;}
 drawPlayer(c,p,time,{alpha=1,x=p.x,y=p.y}={}){const state=p.hurtAnim>0?'hit':p.dashAnim>0?'dash':p.attackAnim>0?'attack':p.moving?'walk':'idle';const duration=state==='dash'?.32:state==='hit'?.38:.38;const clock=['idle','walk'].includes(state)?time:duration-({hit:p.hurtAnim,dash:p.dashAnim,attack:p.attackAnim}[state]||0);const {row,frame}=animationFrame(state,Math.max(0,clock),duration);c.save();c.translate(x,y);c.globalAlpha=alpha;if(p.face.x<-.1)c.scale(-1,1);if(p.inv>0&&p.dashAnim<=0)c.globalAlpha*=.55+Math.abs(Math.sin(time*25))*.45;const ok=this.cell(c,this.player,frame,row,4,5,-55,-96,110,110);c.restore();return ok;}
 drawEnemy(c,e,stage,boss,time){const width=boss?212:e.role==='tank'?120:106,height=width*.75;const bob=e.freeze>0?0:Math.sin(time*(boss?2:5)+(e.seed||0))*3;const recoil=e.hitFlash>0?Math.sin(e.hitFlash*50)*6:0;c.save();c.translate(e.x+recoil,e.y+bob);if(e.facing<0)c.scale(-1,1);if(e.windup>0)c.scale(1.08,.94);if(e.hitFlash>0)c.filter='brightness(1.8)';else if(e.freeze>0)c.filter='saturate(.2) brightness(1.4)';const ok=this.cell(c,this.enemies,boss?2:e.variant||0,stage,3,6,-width/2,-height*.8,width,height);c.restore();return ok;}
}
